//! The GitHub Actions workflow `gate sync` writes from `[ci.github]`.

use std::collections::BTreeSet;

use serde_json::{Map, Value, json};

use super::hooks::LAUNCHER;
use super::yaml::to_yaml;
use crate::config::{Budget, CiGithub, CiJob, CiStep, NeedsWhen, RelativePath};
use crate::error::{Error, Result};
use crate::projects::Projects;

/// The first line of the generated workflow.
pub const WORKFLOW_MARKER: &str =
    "# Generated by gate sync from gate.toml [ci.github]; edit gate.toml, then run gate sync.";

/// The runner when the configuration names none.
pub const DEFAULT_RUNNER: &str = "ubuntu-24.04";

/// The id of the generated first job, which lists the changed projects.
pub const CHANGES_JOB: &str = "changes";

/// The display name of the `changes` job.
pub const CHANGES_NAME: &str = "Changes";

/// The time limit of the `changes` job, in minutes: it checks the generated files and lists the
/// changed projects, which fetches the plugins on a cold cache.
pub const CHANGES_TIMEOUT_MINUTES: u64 = 15;

/// The time limit of the aggregate job, in minutes: one `jq` line.
pub const AGGREGATE_TIMEOUT_MINUTES: u64 = 5;

/// The name of the checkout step of every generated job.
pub const CHECKOUT_STEP: &str = "Check out the repository";

/// The pushed range the `changes` job compares: the pull request's base or the push's previous tip
/// (zeros, which select every project, when there is neither), to the commit under test.
const RANGE: &str = "${{ github.event.pull_request.base.sha || github.event.before || '0000000000000000000000000000000000000000' }}..${{ github.sha }}";

/// The remote ref a pushed range goes to, always a full ref: `refs/heads/<base branch>` for a pull
/// request, the pushed ref otherwise.
const TARGET_REF: &str =
    "${{ github.base_ref && format('refs/heads/{0}', github.base_ref) || github.ref }}";

/// The concurrency group of a run of the workflow at `path`: the file's path, so no other workflow
/// shares it whatever its display name, and the ref, so a pull request's runs
/// (`refs/pull/<n>/merge`) and a branch's runs (`refs/heads/<name>`) each queue apart.
fn concurrency_group(path: &str) -> String {
    format!("{path}@${{{{ github.ref }}}}")
}

/// Whether a newer run of the group cancels the one in progress: for every ref but the default
/// branch, since a superseded commit of a pull request or a branch is never the one that merges;
/// never on the default branch, so a push there never cancels a running check of it.
pub const CANCEL_IN_PROGRESS: &str =
    "${{ github.ref != format('refs/heads/{0}', github.event.repository.default_branch) }}";

/// The action that restores the Gate cache, pinned by commit with its release.
pub const CACHE_RESTORE: &str =
    "actions/cache/restore@55cc8345863c7cc4c66a329aec7e433d2d1c52a9 # v6.1.0";

/// The action that saves the Gate cache: the same commit as [`CACHE_RESTORE`].
pub const CACHE_SAVE: &str = "actions/cache/save@55cc8345863c7cc4c66a329aec7e433d2d1c52a9 # v6.1.0";

/// The Gate cache of a job with `[ci.github] cache`, given to its `bin/gate` steps as
/// `GATE_CACHE_DIR`. `runner.temp` is emptied at the start and end of every job, so the directory
/// holds what the restore step put there and nothing else. GitHub does not allow the `runner`
/// context in a job's `env`, so the variable sits on the steps.
pub const CACHE_DIR: &str = "${{ runner.temp }}/gate-cache";

/// The parts of the Gate cache a job restores and saves. `blobs` is hashed again against its pin on
/// every read; `modules`, `results`, `declarations` and `git` are derived and trusted as restored,
/// which is why the cache is opt-in. Never `core` or `tools`: `bin/gate` and the tools check what
/// is unpacked there against a sha256 recorded in the cache itself, not against `gate.lock`, so
/// each job downloads and verifies them again.
pub const CACHED: [&str; 5] = ["blobs", "modules", "results", "declarations", "git"];

/// The id of the step that restores the Gate cache, whose outputs the save step reads.
const CACHE_STEP_ID: &str = "gate-cache";

/// The id of a job's last `bin/gate` step with `[ci.github] cache`, whose outcome the save step
/// reads; the `changes` job's is `changes`.
const LAST_GATE_STEP_ID: &str = "gate-run";

/// The start of every key of the Gate cache: `/` separates the parts, since no job id holds one.
/// The architecture keeps an x86 and an Arm runner of one OS apart.
const CACHE_KEY_PREFIX: &str = "gate/${{ runner.os }}/${{ runner.arch }}/";

/// The part of a key after the job: the hash of `gate.lock`. It comes after the job, so that one
/// restore key can match the job's entries under any lock.
const CACHE_KEY_LOCK: &str = "${{ hashFiles('gate.lock') }}/";

/// The token a `bin/gate` step reads private plugin releases with: the repository secret
/// `GATE_GITHUB_TOKEN` when it is set, else the job's own token. Only `bin/gate` steps get it; other
/// steps and actions do not.
const TOKEN: &str = "${{ secrets.GATE_GITHUB_TOKEN || github.token }}";

/// The branch under test: a pull request's head branch (its checkout is a detached HEAD), else the
/// pushed branch. Passed through the environment, never written into a command line.
const BRANCH: &str = "${{ github.head_ref || github.ref_name }}";

/// The environment of a `bin/gate` step: the token and the branch, with `cached` the Gate cache's
/// directory, and with `pushed` the range and the remote ref of `--push`.
fn gate_env(cached: bool, pushed: bool) -> Value {
    let mut env = Map::new();
    env.insert("GATE_BRANCH".to_owned(), json!(BRANCH));
    if cached {
        env.insert("GATE_CACHE_DIR".to_owned(), json!(CACHE_DIR));
    }
    env.insert("GATE_GITHUB_TOKEN".to_owned(), json!(TOKEN));
    if pushed {
        env.insert("GATE_RANGE".to_owned(), json!(RANGE));
        env.insert("GATE_TARGET_REF".to_owned(), json!(TARGET_REF));
    }
    Value::Object(env)
}

/// The workflow file's text. `history` holds the ids of the jobs whose gate commands need the
/// whole history (a rule that reads it, a pushed range, a revision).
///
/// # Errors
/// Fails when a job names a project the repository does not have.
pub fn workflow(
    github: &CiGithub,
    projects: &Projects,
    history: &BTreeSet<String>,
) -> Result<String> {
    let branches: Vec<&str> = if github.branches.is_empty() {
        vec!["main"]
    } else {
        github.branches.iter().map(String::as_str).collect()
    };
    let runner = github.runs_on.as_deref().unwrap_or(DEFAULT_RUNNER);
    let cached = github.cache;

    let mut steps = vec![checkout(github, Some(0))];
    if cached {
        steps.push(cache_restore(CHANGES_JOB));
    }
    steps.extend([
        json!({
            "name": "Check the generated files",
            "run": format!("{LAUNCHER} sync --check"),
            "env": gate_env(cached, false),
        }),
        json!({
            "id": "changes",
            "name": "List the changed projects",
            "run": format!(
                "{LAUNCHER} check --list-changed-projects --format github-output --push \"$GATE_RANGE\" --target-ref \"$GATE_TARGET_REF\" >> \"$GITHUB_OUTPUT\""
            ),
            "env": gate_env(cached, true),
        }),
    ]);
    if cached {
        steps.extend(cache_end(CHANGES_JOB, CHANGES_JOB));
    }
    let mut jobs = Map::new();
    jobs.insert(
        CHANGES_JOB.to_owned(),
        json!({
            "name": CHANGES_NAME,
            "runs-on": runner,
            "timeout-minutes": CHANGES_TIMEOUT_MINUTES,
            "permissions": { "contents": "read" },
            "outputs": { "projects": "${{ steps.changes.outputs.projects }}" },
            "steps": steps,
        }),
    );

    for (id, job) in &github.jobs {
        let depth = job
            .fetch_depth
            .or_else(|| history.contains(id.as_str()).then_some(0));
        jobs.insert(
            id.to_string(),
            job_value(id.as_str(), job, github, depth, projects)?,
        );
    }

    if let Some(aggregate) = &github.aggregate {
        let needs: Vec<String> = jobs.keys().cloned().collect();
        let name = github
            .aggregate_name
            .as_deref()
            .unwrap_or(aggregate.as_str());
        jobs.insert(aggregate.to_string(), aggregate_value(name, runner, &needs));
    }

    let document = json!({
        "name": github.name.as_deref().unwrap_or("Gate"),
        "on": {
            "push": { "branches": branches },
            "pull_request": { "branches": branches },
        },
        "permissions": {},
        "concurrency": {
            "group": concurrency_group(github.workflow.as_str()),
            "cancel-in-progress": CANCEL_IN_PROGRESS,
        },
        "jobs": jobs,
    });

    Ok(format!("{WORKFLOW_MARKER}\n{}", to_yaml(&document)))
}

/// The aggregate job's command: with `toJSON(needs)` in `NEEDS`, it prints each needed job whose
/// result is neither `success` nor `skipped`, and then fails. `jq` ships with GitHub's runners.
pub const AGGREGATE_SCRIPT: &str = r#"failed=$(printf '%s' "$NEEDS" | jq -r 'to_entries[] | select(.value.result != "success" and .value.result != "skipped") | "\(.key) is \(.value.result)"'); if [ -n "$failed" ]; then printf 'jobs that neither succeeded nor were skipped:\n%s\n' "$failed"; exit 1; fi"#;

/// The aggregate job: it needs every job in `needs` and runs even when one of them failed or was
/// cancelled, so it fails then instead of being skipped. It checks out nothing and holds no token
/// permission. Its `name`, the check name branch protection requires, is `aggregate-name`, else
/// its id.
fn aggregate_value(name: &str, runner: &str, needs: &[String]) -> Value {
    json!({
        "name": name,
        "runs-on": runner,
        "timeout-minutes": AGGREGATE_TIMEOUT_MINUTES,
        "needs": needs,
        "if": "${{ always() }}",
        "permissions": {},
        "steps": [
            {
                "name": "Require every job to succeed or be skipped",
                "run": AGGREGATE_SCRIPT,
                "env": { "NEEDS": "${{ toJSON(needs) }}" },
            },
        ],
    })
}

/// The paths of the Gate cache a job restores and saves, one per line, as `actions/cache` reads
/// them: the parts of [`CACHED`], each under [`CACHE_DIR`].
#[must_use]
pub fn cache_paths() -> String {
    CACHED
        .iter()
        .map(|part| format!("{CACHE_DIR}/{part}"))
        .collect::<Vec<_>>()
        .join("\n")
}

/// The step that restores the Gate cache of the job `id`: the entry of this commit, else the newest
/// of the job under the same `gate.lock`, else the newest of the job under any lock, so that a move
/// of a pin starts warm, else the newest of any job. A restored part is keyed by what produced it:
/// a plugin's download by its sha256, which the run takes from the current `gate.lock` and hashes
/// again on every read; its declaration and results by that sha256 and the core's version. A part
/// written for a pin that moved is never looked up, so it is unused, never wrong.
fn cache_restore(id: &str) -> Value {
    let job = format!("{CACHE_KEY_PREFIX}{id}/");
    json!({
        "id": CACHE_STEP_ID,
        "name": "Restore the Gate cache",
        "uses": CACHE_RESTORE,
        "with": {
            "path": cache_paths(),
            "key": format!("{job}{CACHE_KEY_LOCK}${{{{ github.sha }}}}"),
            "restore-keys": format!("{job}{CACHE_KEY_LOCK}\n{job}\n{CACHE_KEY_PREFIX}"),
        },
    })
}

/// How many days a derived file of the Gate cache (a result, a declaration, a stored git content)
/// may go unused before the prune of a generated job removes it. A run sets the time of each such
/// file it uses, and `actions/cache` keeps file times through a save and a restore. So the bound
/// removes what a previous core left (its results and declarations are keyed by its version), and
/// results no input of the job asks for any more.
pub const CACHE_PRUNE_DAYS: u64 = 30;

/// The steps that end the job `job` with `[ci.github] cache`: the prune, then the save, both under
/// [`cache_saved`].
///
/// The prune removes what the current `gate.lock` no longer pins: the downloads, declarations and
/// results of plugin pins that moved, and the previous core's download. With
/// [`CACHE_PRUNE_DAYS`], it also removes derived files unused that long, among them a previous
/// core's results and declarations. A job restores an entry saved under an earlier lock, so
/// without the prune every entry would carry each earlier pin forward. While the lock pins a
/// plugin, `modules/` stays whole, since its files do not say which plugin they came from.
///
/// A cache it cannot prune fails the step: the core says what is wrong and the local fix, and the
/// step adds the CI fix, deleting the job's entries.
///
/// The save stores the cache under the key the restore step tried.
fn cache_end(job: &str, last: &str) -> [Value; 2] {
    let condition = cache_saved(last);
    [
        json!({
            "name": "Prune the Gate cache",
            "if": condition,
            "run": format!(
                "{LAUNCHER} cache prune --yes --older-than {CACHE_PRUNE_DAYS} || {{ echo \"::error title=Gate cache::the prune of the Gate cache failed (see above). To start this job from an empty cache, delete its entries on this branch and on the default branch, with gh cache list --key {CACHE_KEY_PREFIX}{job}/ --ref <ref> and gh cache delete <id>\"; exit 1; }}"
            ),
            "env": gate_env(true, false),
        }),
        json!({
            "name": "Save the Gate cache",
            "if": condition,
            "uses": CACHE_SAVE,
            "with": {
                "path": cache_paths(),
                "key": format!("${{{{ steps.{CACHE_STEP_ID}.outputs.cache-primary-key }}}}"),
            },
        }),
    ]
}

/// When a job prunes and saves the Gate cache. A red check saves too, because its results are as
/// valid as a green one's. A job does not save:
/// - when the run was cancelled or the job timed out;
/// - when its last `bin/gate` step (`last`, its step id) never ran, so that a job that failed
///   before it saves nothing a rerun would then find under this commit's key;
/// - when the restore step found this very key (a rerun).
///
/// An entry found by a restore key is not a hit, including one saved under another `gate.lock`.
/// So the job saves under the current lock, and the next run starts from that.
fn cache_saved(last: &str) -> String {
    format!(
        "${{{{ !cancelled() && steps.{last}.outcome != 'skipped' && steps.{CACHE_STEP_ID}.outputs.cache-hit != 'true' }}}}"
    )
}

/// The checkout step, named, with `fetch-depth` when one is set. It keeps no credentials
/// (`persist-credentials: false`): a token left in the clone's git configuration reaches every later
/// step and any artifact of the workspace. No setting keeps them, since the generated jobs never
/// push and read private plugin releases through `GATE_GITHUB_TOKEN`, not through git.
fn checkout(github: &CiGithub, depth: Option<u64>) -> Value {
    let mut with = Map::new();
    if let Some(depth) = depth {
        with.insert("fetch-depth".to_owned(), json!(depth));
    }
    with.insert("persist-credentials".to_owned(), json!(false));
    json!({ "name": CHECKOUT_STEP, "uses": github.checkout, "with": with })
}

/// The condition of a job that needs some projects, without `${{ }}`: it runs when one of them
/// changed, and also when the `changes` job did not succeed (a base the clone cannot reach, say),
/// since then nobody knows what changed; a job skipped for that would count as passing.
fn projects_terms(projects: &[String]) -> String {
    let changed = projects
        .iter()
        .map(|project| {
            format!("contains(fromJSON(needs.{CHANGES_JOB}.outputs.projects), '{project}')")
        })
        .collect::<Vec<_>>()
        .join(" || ");
    format!("!cancelled() && (needs.{CHANGES_JOB}.result != 'success' || {changed})")
}

/// The `needs:` and `if:` of a job, `None` when it lists neither `projects` nor `needs`.
///
/// `needs:` holds `changes` first when the job lists projects, then the jobs of its `needs` as
/// written. The condition starts with `!cancelled()`, so a failed or skipped job in `needs` never
/// skips this one by GitHub's implicit `success()`; it adds the projects condition when the job
/// lists projects, and with `when = "succeeded"` that every job of `needs` succeeded.
#[must_use]
pub fn needs_and_condition(job: &CiJob) -> Option<(Vec<String>, String)> {
    if job.projects.is_empty() && job.needs.is_empty() {
        return None;
    }
    let mut needs = Vec::new();
    let mut terms = Vec::new();
    if job.projects.is_empty() {
        terms.push("!cancelled()".to_owned());
    } else {
        needs.push(CHANGES_JOB.to_owned());
        terms.push(projects_terms(&job.projects));
    }
    for need in &job.needs {
        needs.push(need.to_string());
        if job.when == Some(NeedsWhen::Succeeded) {
            terms.push(format!("needs.{need}.result == 'success'"));
        }
    }
    Some((needs, format!("${{{{ {} }}}}", terms.join(" && "))))
}

/// The words of a job's gate command as the workflow runs it: `check` gets `--no-overrides` and
/// the thresholds of the job's budget, a `--push` gets the pushed range and `--target-ref` right
/// after it. Returns the words and whether the range variables are used.
#[must_use]
pub fn command_words(command: &str, budget: Option<&Budget>) -> (Vec<String>, bool) {
    let mut words: Vec<String> = command.split_whitespace().map(str::to_owned).collect();
    let pushed = match words.iter().position(|word| word == "--push") {
        Some(at) => {
            let rest = words.split_off(at + 1);
            words.extend([
                "\"$GATE_RANGE\"".to_owned(),
                "--target-ref".to_owned(),
                "\"$GATE_TARGET_REF\"".to_owned(),
            ]);
            words.extend(rest);
            true
        }
        None => false,
    };
    if words.first().is_some_and(|word| word == "check") {
        if !words.iter().any(|word| word == "--no-overrides") {
            words.push("--no-overrides".to_owned());
        }
        let flags = super::budget_flags(budget, &words);
        words.extend(flags);
    }
    (words, pushed)
}

fn job_value(
    id: &str,
    job: &CiJob,
    github: &CiGithub,
    depth: Option<u64>,
    projects: &Projects,
) -> Result<Value> {
    let mut value = Map::new();
    value.insert("name".to_owned(), json!(job.name));
    value.insert(
        "runs-on".to_owned(),
        json!(job.runs_on.as_deref().unwrap_or(DEFAULT_RUNNER)),
    );

    if !job.projects.is_empty() {
        for project in &job.projects {
            if projects.get(project).is_none() {
                return Err(Error::config(format!(
                    "gate.toml: [ci.github] jobs.{id}: projects names {project:?}, which is not a project; gate list prints the project names"
                )));
            }
        }
    }
    if let Some((needs, condition)) = needs_and_condition(job) {
        value.insert("needs".to_owned(), json!(needs));
        value.insert("if".to_owned(), json!(condition));
    }

    if let Some(minutes) = job.timeout_minutes {
        value.insert("timeout-minutes".to_owned(), json!(minutes));
    }

    let permissions: Map<String, Value> = if job.permissions.is_empty() {
        std::iter::once(("contents".to_owned(), json!("read"))).collect()
    } else {
        job.permissions
            .iter()
            .map(|(scope, access)| (scope.clone(), json!(access)))
            .collect()
    };
    value.insert("permissions".to_owned(), Value::Object(permissions));
    if let Some(environment) = &job.environment {
        value.insert("environment".to_owned(), json!(environment));
    }

    if !job.services.is_empty() {
        let services: Map<String, Value> = job
            .services
            .iter()
            .map(|(name, service)| (name.clone(), service.clone()))
            .collect();
        value.insert("services".to_owned(), Value::Object(services));
    }

    let directory = job.working_directory.as_ref().map(RelativePath::as_str);
    let mut steps = vec![checkout(github, depth)];
    if github.cache {
        steps.push(cache_restore(id));
    }
    steps.extend(github.setup.iter().map(|step| step_value(step, None)));
    steps.extend(job.steps.iter().map(|step| step_value(step, directory)));

    for (index, command) in job.run.iter().enumerate() {
        let (words, pushed) = command_words(command, job.budget.as_ref());
        let mut step = Map::new();
        if github.cache && index + 1 == job.run.len() {
            step.insert("id".to_owned(), json!(LAST_GATE_STEP_ID));
        }
        step.insert("name".to_owned(), json!(format!("gate {command}")));
        step.insert(
            "run".to_owned(),
            json!(format!("{LAUNCHER} {}", words.join(" "))),
        );
        step.insert("env".to_owned(), gate_env(github.cache, pushed));
        steps.push(Value::Object(step));
    }
    steps.extend(job.after.iter().map(|step| step_value(step, directory)));
    if github.cache {
        steps.extend(cache_end(id, LAST_GATE_STEP_ID));
    }
    value.insert("steps".to_owned(), Value::Array(steps));

    Ok(Value::Object(value))
}

fn step_value(step: &CiStep, directory: Option<&str>) -> Value {
    let mut value = Map::new();
    if let Some(name) = &step.name {
        value.insert("name".to_owned(), json!(name));
    }
    if let Some(condition) = &step.condition {
        value.insert("if".to_owned(), json!(condition));
    }
    if let Some(uses) = &step.uses {
        value.insert("uses".to_owned(), json!(uses));
    }
    if !step.with.is_empty() {
        let with: Map<String, Value> = step
            .with
            .iter()
            .map(|(key, input)| (key.clone(), input.clone()))
            .collect();
        value.insert("with".to_owned(), Value::Object(with));
    }
    if let Some(run) = &step.run {
        value.insert("run".to_owned(), json!(run));
        if let Some(directory) = step
            .working_directory
            .as_ref()
            .map(RelativePath::as_str)
            .or(directory)
        {
            value.insert("working-directory".to_owned(), json!(directory));
        }
    }
    if !step.env.is_empty() {
        let env: Map<String, Value> = step
            .env
            .iter()
            .map(|(key, variable)| (key.clone(), json!(variable)))
            .collect();
        value.insert("env".to_owned(), Value::Object(env));
    }
    Value::Object(value)
}
